def write(path,text): path.parent.mkdir(exist_ok=True,parents=True);path.write_text(text)
def asset(name): return "{{ '"+name+"' | asset_url }}"
def section(name,body,settings=None,blocks=None):
 schema={'name':name.replace('jp-','').replace('-',' ').title(),'settings':settings or [],'presets':[{'name':name.replace('jp-','').replace('-',' ').title()}]}
 if blocks: schema['blocks']=blocks
 write(T/'sections'/(name+'.liquid'),body+'\n{% schema %}\n'+json.dumps(schema,indent=2)+'\n{% endschema %}')
 return body
