settings=[{'name':'theme_info','theme_name':'JobPlug — Next Chapter','theme_version':'1.0.0','theme_author':'JobPlug','theme_documentation_url':'https://www.jobplug.co','theme_support_url':'https://www.jobplug.co/pages/contact'},{'name':'Booking and intake','settings':[{'type':'url','id':'calendly_url','label':'Calendly booking URL','info':'Use the event URL without query parameters.'},{'type':'url','id':'google_form_url','label':'Google Form respondent URL','info':'Use the full Google Forms viewform URL without query parameters. Submissions go directly to this form.'}]}]
write(T/'config/settings_schema.json',json.dumps(settings,indent=2));write(T/'config/settings_data.json',json.dumps({'current':{'calendly_url':CAL,'google_form_url':FORM},'presets':{}},indent=2));write(T/'locales/en.default.json','{}')
layout='''<!doctype html><html lang="{{ request.locale.iso_code }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="canonical" href="{{ canonical_url }}"><title>{{ page_title | escape }}{% unless page_title contains shop.name %} | {{ shop.name | escape }}{% endunless %}</title>{% if page_description %}<meta name="description" content="{{ page_description | escape }}">{% else %}<meta name="description" content="Personalized career coaching, résumé support, interview preparation, and job-search services from JobPlug.">{% endif %}<meta property="og:title" content="{{ page_title | escape }}"><meta property="og:url" content="{{ canonical_url }}"><meta property="og:site_name" content="{{ shop.name | escape }}"><meta property="og:type" content="website">{{ content_for_header }}{{ 'jobplug.css' | asset_url | stylesheet_tag }}<script src="{{ 'jobplug.js' | asset_url }}" defer></script></head><body><a class="skip" href="#main">Skip to content</a>{% render 'jp-header' %}<main id="main" tabindex="-1">{{ content_for_layout }}</main>{% render 'jp-footer' %}</body></html>'''
write(T/'layout/theme.liquid',layout)
# Static preview uses the same section markup, stylesheet, and scripts as the theme.
def render(text):
 for key,value in [('heading','You bring the ambition.'),('accent','We bring the plan.'),('description','From a stronger résumé to a smarter job search, get the guidance and hands-on support to move toward a career that fits you.')]: text=text.replace('{{ section.settings.'+key+' | escape }}',value)
 text=re.sub(r"{% assign package_product = all_products\['([^']+)'\] %}(.*?)(?={% assign package_product|$)",lambda m: m[2].replace('{{ package_product.variants.first.price | money }}','$'+by[m[1]]['variants'][0]['price'].removesuffix('.00')),text,flags=re.S)
 text=re.sub(r"{{ '([^']+)' \| asset_url }}",r'/assets/\1',text)
 text=text.replace('{{ settings.calendly_url | escape }}',CAL).replace('{{ settings.google_form_url | escape }}',FORM).replace('{{ "now" | date: "%Y" }}','2026')
 text=re.sub(r'{% for policy.*?{% endfor %}','',text,flags=re.S)
 return text
preview_note='<div class="preview-note">DESIGN PREVIEW · Connected to the existing booking and intake links · Purchases use the current store</div>'
def page(path,title,body):
 full='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' | JobPlug</title><meta name="robots" content="noindex"><link rel="stylesheet" href="/assets/jobplug.css"><script defer src="/assets/jobplug.js"></script></head><body><a class="skip" href="#main">Skip to content</a>'+preview_note+header+'<main id="main" tabindex="-1">'+render(body)+'</main>'+render(footer)+'</body></html>'
 write(P/path/'index.html' if path else P/'index.html',full)
