page('collections/packages','Career packages',packages+faq+cta)
page('pages/contact','Contact JobPlug','<section class="wrap section"><span class="eyebrow">Let’s connect</span><h1>What’s on your mind?</h1><p style="margin:25px 0">Our contact form is available on the current JobPlug store.</p>'+button('Contact JobPlug','https://www.jobplug.co/pages/contact')+'<p class="small" style="margin-top:20px">The new theme uses Shopify’s native contact form once installed.</p></section>')
page('cart','Your cart','<section class="wrap section"><h1>Ready for your next step?</h1><p style="margin:25px 0">Purchases and cart updates are handled by the current JobPlug store while this redesign is in preview.</p>'+button('Open your Shopify cart','https://www.jobplug.co/cart')+'</section>')
for product in products:
 handle=product['handle'];im=product['images'][0]['src'] if product['images'] else '/assets/career-work.jpg';title=html.escape(product['title']);price=product['variants'][0]['price']
 desc=product['body_html']
 if handle in ['mock-technical-interview','30-day-tech-interview-vip-package-land-your-dream-job']:
  desc='<h2>Support for your next role</h2><p>Application support, an industry-tailored mock interview, curated job alerts, and VIP event access.</p><p>The 30-day interview commitment provides a free career strategy session if no interview is secured. Confirm eligibility and the start date with JobPlug.</p><p>Discuss deposit and payment-plan terms during a consultation.</p>'
 buy=button('Discuss payment options','/pages/free-consultant') if handle=='mock-technical-interview' else button('View on the current store','https://www.jobplug.co/products/'+handle)
 page('products/'+handle,title,'<section class="wrap section"><div class="breadcrumb"><a href="/collections/services">Services</a> / '+title+'</div><div class="product-layout"><div><img class="product-image" src="'+im+'" alt="'+title+'" width="1000" height="750"><div class="notice">Not sure? <a class="text-link" href="/pages/free-consultant">Book a consultation ↗</a></div></div><div><span class="eyebrow">Your next step, supported</span><h1>'+title+'</h1>'+('' if handle=='mock-technical-interview' else '<div class="price">$'+price+'</div>')+'<div class="actions">'+buy+'</div><div class="prose product-description">'+desc+'</div></div></div></section>')
# Preserve blog text and internal URLs in the redesigned preview.
blogcards=[]
for f in E.glob('blogs__news__*.main.html'):
 raw=f.read_text();match=re.search(r'<h1[^>]*>(.*?)</h1>',raw,re.S);title=re.sub('<[^>]+>','',match[1]).strip() if match else f.stem
 handle=f.name.split('__')[-1].replace('.main.html','')
 article=re.search(r'<div[^>]*class="[^"]*article-template__content[^>]*>(.*?)</div>',raw,re.S)
 body=article[1] if article else '<p>Read this resource on JobPlug.</p><a class="text-link" href="https://www.jobplug.co/blogs/news/'+handle+'">Open the article ↗</a>'
 page('blogs/news/'+handle,title,'<article class="wrap section prose"><span class="eyebrow">Career resources</span><h1 style="font-size:44px">'+title+'</h1>'+body+'</article>')
 blogcards.append('<article class="service-card"><span class="service-icon">↗</span><h3>'+title+'</h3><p>Practical guidance for your career journey.</p><a href="/blogs/news/'+handle+'">Read the article ↗</a></article>')
page('blogs/news','Career resources','<div class="wrap page-top"><span class="eyebrow">A little guidance for the road</span><h1>Career resources.</h1></div><section class="wrap section"><div class="service-grid">'+''.join(blogcards)+'</div></section>')
for f in T.rglob('*.liquid'):
 text=f.read_text().replace('href="/"', 'href="{{ routes.root_url }}"').replace('href="/collections/', 'href="{{ routes.collections_url }}/').replace('href="/cart"', 'href="{{ routes.cart_url }}"')
 f.write_text(text)
with zipfile.ZipFile(R/'jobplug-shopify-theme.zip','w',zipfile.ZIP_DEFLATED) as z:
 for directory in ['assets','config','layout','locales','sections','snippets','templates']:
  for f in (T/directory).rglob('*'):
   if f.is_file(): z.write(f,f.relative_to(T))
